using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageRequirementTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace Test
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int Value { get; set; }
            }
        }
        """;

    [Fact]
    public async Task GeneratedObjectFormatter_IsExcludedFromCodeCoverage()
    {
        Compilation output = await RunGeneratorAsync(Source);
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        INamedTypeSymbol formatter = FindFormatterFor(output, "MyObject");
        Assert.True(HasExcludeFromCodeCoverage(formatter), $"Generated formatter {formatter.ToDisplayString()} lacks [ExcludeFromCodeCoverage].");
    }

    [Fact]
    public async Task GeneratedResolver_IsExcludedFromCodeCoverage()
    {
        Compilation output = await RunGeneratorAsync(Source);
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("Test.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasExcludeFromCodeCoverage(resolver!), "Generated resolver lacks [ExcludeFromCodeCoverage].");
    }

    private static bool HasExcludeFromCodeCoverage(INamedTypeSymbol symbol)
        => symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static INamedTypeSymbol FindFormatterFor(Compilation output, string dataTypeName)
    {
        foreach (SyntaxTree tree in output.SyntaxTrees)
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax declaration in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(declaration) is INamedTypeSymbol symbol &&
                    symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" && i.TypeArguments.Length == 1 && i.TypeArguments[0].Name == dataTypeName))
                {
                    return symbol;
                }
            }
        }

        throw new InvalidOperationException($"No generated formatter found for {dataTypeName}.");
    }

    private static async Task<Compilation> RunGeneratorAsync(string source, params string[] preprocessorSymbols)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp12, preprocessorSymbols: preprocessorSymbols);
        ImmutableArray<MetadataReference> frameworkReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            frameworkReferences.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        Assert.DoesNotContain(generatorDiagnostics, d => d.Severity == DiagnosticSeverity.Error);
        return output;
    }
}

